import{f as e,o as t,c as o,a2 as d}from"./chunks/framework.Cd9rfTEn.js";const m=JSON.parse('{"title":"Catálogo de endpoints de la API","description":"","frontmatter":{},"headers":[],"relativePath":"entregables-analisis-diseno/18-catalogo-endpoints.md","filePath":"entregables-analisis-diseno/18-catalogo-endpoints.md","lastUpdated":null}'),r={name:"entregables-analisis-diseno/18-catalogo-endpoints.md"};function i(n,a,s,c,l,p){return t(),o("div",null,[...a[0]||(a[0]=[d('<h1 id="catalogo-de-endpoints-de-la-api" tabindex="-1">Catálogo de endpoints de la API <a class="header-anchor" href="#catalogo-de-endpoints-de-la-api" aria-label="Permalink to &quot;Catálogo de endpoints de la API&quot;">​</a></h1><p>Artefacto 7.1 del índice de entregables, complemento de <a href="./18-contratos-api"><code>18-contratos-api.md</code></a>. Responde, para cada API y cada endpoint, <strong>para qué sirve, qué hace, quién lo usa, qué recibe y qué devuelve</strong>, en lenguaje de negocio. Los contratos técnicos están en <code>18-openapi/</code> y se navegan en el <a href="./18-swagger/index.html">visor Swagger</a>, que muestra la misma ficha en cada operación.</p><p>Generado el 05-11-2026 con <code>_trabajo/gen_18_catalogo_endpoints.py</code> (textos de <code>_trabajo/endpoints_lib.py</code>). No se edita a mano: tras regenerar <code>18-openapi/</code>, se ejecutan este script y <code>_trabajo/gen_swagger.py</code>.</p><h2 id="como-esta-organizada-la-api" tabindex="-1">Cómo está organizada la API <a class="header-anchor" href="#como-esta-organizada-la-api" aria-label="Permalink to &quot;Cómo está organizada la API&quot;">​</a></h2><p>Hay <strong>una API por módulo</strong> (anexo de la especificación) y una <strong>API externa</strong> para terceros. Dentro de cada API los endpoints se agrupan por función (las subsecciones del §11 del anexo: backoffice, portal, campo, etc.). El primer segmento de la ruta dice quién la usa:</p><table tabindex="0"><thead><tr><th>Prefijo de ruta</th><th>Quién la usa</th></tr></thead><tbody><tr><td><code>/api/admin/&amp;lt;mod&gt;/...</code></td><td>Personal de la cooperativa, desde el backoffice</td></tr><tr><td><code>/api/por/...</code>, <code>/api/portal/...</code>, <code>/api/me/...</code>, <code>/api/&amp;lt;mod&gt;/my/...</code></td><td>Socio, desde el portal y la app de autogestión</td></tr><tr><td><code>/api/field/...</code>, <code>/api/&amp;lt;mod&gt;/collector/...</code></td><td>Personal de campo y cobradores, desde la app móvil</td></tr><tr><td><code>/api/platform/...</code></td><td>Equipo de GoodApps, desde la consola de plataforma (todos los tenants)</td></tr><tr><td><code>/api/public/{tenantSlug}/...</code>, <code>/l/...</code></td><td>Cualquier persona, sin iniciar sesión</td></tr><tr><td><code>/api/auth/...</code></td><td>Inicio y administración de sesión</td></tr><tr><td><code>/api/v1/ext/...</code></td><td>Sistemas de terceros con credenciales de cliente</td></tr><tr><td><code>/api/internal/...</code>, <code>/health</code>, <code>/readyz</code></td><td>Uso interno y monitoreo</td></tr></tbody></table><h2 id="las-apis" tabindex="-1">Las APIs <a class="header-anchor" href="#las-apis" aria-label="Permalink to &quot;Las APIs&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Anexo</th><th>API</th><th>Para qué sirve</th><th>Endpoints</th><th>Catálogo</th><th>Swagger</th></tr></thead><tbody><tr><td>M01</td><td>Personas, titulares, asociados, cuentas, inmuebles y domicilios</td><td>Mantener, dentro de cada cooperativa (tenant), una identidad de negocio única y consistente de cada persona física o jurídica y de todas sus relaciones con esa cooperativa: titularidad comercial, condición de asociado (solo el vínculo; el detalle institucional es de M17), cuentas, domicilios, inmuebles, puntos de…</td><td>108</td><td><a href="./18-catalogo-endpoints/m01-per">m01-per</a></td><td><a href="./18-swagger/index.html?api=m01-per">abrir</a></td></tr><tr><td>M02</td><td>Catálogo de servicios, productos, planes, categorías, estados, contrato de servicio, habilitación por tenant, copia entre tenants y particularidades por servicio</td><td>Definir, sin necesidad de programar, qué servicios puede prestar cada cooperativa (tenant), con qué productos, planes, categorías, conceptos facturables, requisitos, estados y reglas propias, y administrar el contrato de servicio (suscripción) que vincula a un titular identificado por DNI/CUIT con una prestación…</td><td>87</td><td><a href="./18-catalogo-endpoints/m02-cat">m02-cat</a></td><td><a href="./18-swagger/index.html?api=m02-cat">abrir</a></td></tr><tr><td>M03</td><td>Medidores, lecturas, consumos, telemedición y prepago</td><td>Transformar la medición física y remota de los servicios medidos (electricidad, agua, gas y cualquier otro servicio con unidad medible que el tenant habilite) en cantidades aprobadas para liquidar, con trazabilidad completa desde el instrumento hasta la factura.</td><td>109</td><td><a href="./18-catalogo-endpoints/m03-med">m03-med</a></td><td><a href="./18-swagger/index.html?api=m03-med">abrir</a></td></tr><tr><td>M04</td><td>Tarifas y motor de cálculo</td><td>Calcular de forma reproducible, explicable y auditable el importe de cada concepto que se liquida a un contrato (suministro/conexión) de cualquier servicio de la cooperativa —energía, agua, cloaca, gas, Internet, TV, telefonía fija y móvil, sepelio, salud, cuotas de obras y vivienda, productos y cargos por evento— a…</td><td>111</td><td><a href="./18-catalogo-endpoints/m04-tar">m04-tar</a></td><td><a href="./18-swagger/index.html?api=m04-tar">abrir</a></td></tr><tr><td>M05</td><td>Facturación: ciclos, lotes y comprobantes</td><td>Convertir las cantidades y cargos aprobados por los módulos de medición (M03) y tarifas (M04) en comprobantes emitidos sin duplicación, controlados y trazables, para cada cooperativa (tenant) y cada uno de sus servicios.</td><td>190</td><td><a href="./18-catalogo-endpoints/m05-fac">m05-fac</a></td><td><a href="./18-swagger/index.html?api=m05-fac">abrir</a></td></tr><tr><td>M06</td><td>Fiscal e impuestos (ARCA, IVA, percepciones, retenciones, regímenes, terceros, reguladores)</td><td>Proveer a cada cooperativa (tenant) un módulo fiscal único que: Autorice ante ARCA (ex AFIP) los comprobantes que emite el módulo de facturación (M05) y otros módulos…; Determine la condición frente al IVA de emisor y receptor, valide la clase de comprobante (en particular la…; Opere como agente de retención y…</td><td>122</td><td><a href="./18-catalogo-endpoints/m06-fis">m06-fis</a></td><td><a href="./18-swagger/index.html?api=m06-fis">abrir</a></td></tr><tr><td>M07</td><td>Cuenta corriente, cobranza, cajas, entes, débitos, pasarelas y conciliación</td><td>Ser la única fuente del saldo comercial de cada titular dentro de su tenant y el único camino por el que entra dinero al sistema.</td><td>114</td><td><a href="./18-catalogo-endpoints/m07-cob">m07-cob</a></td><td><a href="./18-swagger/index.html?api=m07-cob">abrir</a></td></tr><tr><td>M08</td><td>Mora, intereses, suspensión, corte, reconexión, financiación y convenios, garantías, incobrables, gestión judicial y prescripción</td><td>Especificar, sin necesidad de otra fuente, el módulo que: Calcula intereses y recargos con un único motor parametrizable y auditable, en los tres momentos en que…; Gestiona la mora como una máquina de estados configurable por servicio y categoría: política de mora (BASE…; Orquesta la suspensión, el corte, la…</td><td>184</td><td><a href="./18-catalogo-endpoints/m08-mor">m08-mor</a></td><td><a href="./18-swagger/index.html?api=m08-mor">abrir</a></td></tr><tr><td>M09</td><td>CRM y atención (solicitudes, reclamos, tickets, mesa de entradas, turnero, canales, bot, IA, actividades internas)</td><td>Centralizar en un expediente único por gestión toda la atención que la cooperativa brinda a sus socios, usuarios no asociados, solicitantes sin cuenta y terceros (organismos, juzgados, proveedores que presentan notas), cualquiera sea el canal de ingreso (portal y app del socio, WhatsApp, email, SMS, teléfono/IVR, chat…</td><td>248</td><td><a href="./18-catalogo-endpoints/m09-crm">m09-crm</a></td><td><a href="./18-swagger/index.html?api=m09-crm">abrir</a></td></tr><tr><td>M10</td><td>Técnica, campo, agenda, instalación, GIS/redes, obras, aprovisionamiento TIC y telefonía</td><td>Especificar de forma completa y desarrollable la operación técnica de la cooperativa en GoodApps Cooperativas: desde que una solicitud de servicio necesita evaluarse en terreno hasta que el trabajo está ejecutado, revisado, con evidencia y con su efecto contractual autorizado. El módulo cubre: Factibilidad técnica de…</td><td>382</td><td><a href="./18-catalogo-endpoints/m10-tec">m10-tec</a></td><td><a href="./18-swagger/index.html?api=m10-tec">abrir</a></td></tr><tr><td>M11</td><td>Ventas, presupuestos y punto de venta</td><td>Gestionar todo lo que la cooperativa vende o cobra por única vez fuera de la liquidación periódica del servicio, con trazabilidad comercial, física, financiera, fiscal y contable: Los conceptos por cobrar en operaciones con titulares (derecho de conexión, instalación, reconexión, cambio…; Los presupuestos a socios…</td><td>70</td><td><a href="./18-catalogo-endpoints/m11-ven">m11-ven</a></td><td><a href="./18-swagger/index.html?api=m11-ven">abrir</a></td></tr><tr><td>M12</td><td>Compras y proveedores</td><td>Conducir la adquisición de bienes y servicios de la cooperativa y su relación con proveedores, desde la necesidad interna hasta la obligación de pago lista para tesorería, con trazabilidad comercial, física, fiscal, financiera y contable (BASE §19, §78): Proveedores completos: datos fiscales, CBU validados, regímenes…</td><td>100</td><td><a href="./18-catalogo-endpoints/m12-cmp">m12-cmp</a></td><td><a href="./18-swagger/index.html?api=m12-cmp">abrir</a></td></tr><tr><td>M13</td><td>Stock, equipos serializados, bienes de uso, RMA y fabricación</td><td>Controlar, con una existencia física única por ubicación, serie y lote, todo lo que la cooperativa tiene, custodia, entrega, consume, presta, vende, repara, fabrica o amortiza: materiales de red y de obra, equipos serializados de cliente (módem, ONU/ONT, router, decodificador, medidor), herramientas, repuestos y…</td><td>143</td><td><a href="./18-catalogo-endpoints/m13-stk">m13-stk</a></td><td><a href="./18-swagger/index.html?api=m13-stk">abrir</a></td></tr><tr><td>M14</td><td>Tesorería y bancos</td><td>Administrar el dinero de cada cooperativa (tenant) con trazabilidad completa desde el hecho que lo origina hasta su acreditación o débito bancario y su efecto contable, para que la gerencia pueda ver cuánto dinero tiene disponible, qué está en tránsito, qué compromisos próximos podrían consumirlo y cuál será su…</td><td>166</td><td><a href="./18-catalogo-endpoints/m14-tes">m14-tes</a></td><td><a href="./18-swagger/index.html?api=m14-tes">abrir</a></td></tr><tr><td>M15</td><td>Contabilidad, centros de costo, múltiples planes de cuentas, escenarios simulados y presupuestos</td><td>Registrar, explicar y exponer el efecto económico de todas las operaciones de cada cooperativa (tenant), de modo que: Cada evento económico de cualquier módulo (facturación, cobranza, pagos, compras, stock, bienes de uso…; La contabilidad pueda reconciliarse siempre con los auxiliares comerciales (cuenta corriente por…</td><td>135</td><td><a href="./18-catalogo-endpoints/m15-con">m15-con</a></td><td><a href="./18-swagger/index.html?api=m15-con">abrir</a></td></tr><tr><td>M16</td><td>Personal y sueldos</td><td>Liquidar los haberes del personal en relación de dependencia de cada cooperativa (tenant), cumplir las obligaciones laborales, de la seguridad social y de Ganancias de 4.ª categoría que la normativa argentina impone al empleador, y registrar su efecto en contabilidad, centros de costo, servicios, tesorería y…</td><td>271</td><td><a href="./18-catalogo-endpoints/m16-sue">m16-sue</a></td><td><a href="./18-swagger/index.html?api=m16-sue">abrir</a></td></tr><tr><td>M17</td><td>Gestión institucional (asociados, capital, asambleas, consejo, INAES)</td><td>Gestionar la relación institucional entre cada persona y su cooperativa (Ley 20.337 y normativa del INAES), de forma trazable y separada de la relación comercial por servicios: el registro de asociados (número, antigüedad, estado institucional, ingreso aprobado por acta, egreso con…; el capital social (cuotas sociales…</td><td>110</td><td><a href="./18-catalogo-endpoints/m17-ins">m17-ins</a></td><td><a href="./18-swagger/index.html?api=m17-ins">abrir</a></td></tr><tr><td>M18</td><td>Servicios sociales, otros servicios y flota</td><td>Gestionar los servicios cooperativos no medidos y los recursos móviles de la cooperativa, cada uno con reglas propias (BASE §93, ESP-001), y no como un abono mensual genérico (BASE §24): grupos de cobertura: adherentes y beneficiarios de un servicio (familiares, convivientes, personas a cargo)…; sepelio y subsidio por…</td><td>116</td><td><a href="./18-catalogo-endpoints/m18-soc">m18-soc</a></td><td><a href="./18-swagger/index.html?api=m18-soc">abrir</a></td></tr><tr><td>M19</td><td>Landing, portal y app del socio (autogestión)</td><td>Dar a cada cooperativa (tenant) una presencia digital propia (landing con su marca, noticias, servicios habilitados, consultas públicas, botón de baja) y a cada persona de su comunidad una aplicación única de autogestión (PWA instalable) en la que pueda: Registrarse de forma sencilla sin ser todavía asociado ni tener…</td><td>192</td><td><a href="./18-catalogo-endpoints/m19-por">m19-por</a></td><td><a href="./18-swagger/index.html?api=m19-por">abrir</a></td></tr><tr><td>T01</td><td>Plataforma SaaS: arquitectura de referencia, stack, multitenancy, tenants, licencias, soporte, ambientes y backups</td><td>Definir, de forma desarrollable sin consultar otra fuente, la plataforma SaaS multitenant sobre la que corre GoodApps Cooperativas: La arquitectura de referencia y el stack (DEC-001 a DEC-004): monorepo derivado de Connectia, adaptado como…; El multitenancy en base única con tenantId obligatorio y su aislamiento…</td><td>106</td><td><a href="./18-catalogo-endpoints/t01-pla">t01-pla</a></td><td><a href="./18-swagger/index.html?api=t01-pla">abrir</a></td></tr><tr><td>T02</td><td>Identidad, autenticación, roles, perfiles, alcance y auditoría</td><td>Definir, de forma única para toda la plataforma GoodApps Cooperativas, quién es cada actor (identidad), cómo prueba que es quien dice ser (autenticación), en qué cooperativa y con qué condición actúa (pertenencia y selección de ámbito), qué puede ver y hacer (perfiles de pantallas, roles funcionales, capabilities…</td><td>128</td><td><a href="./18-catalogo-endpoints/t02-iam">t02-iam</a></td><td><a href="./18-swagger/index.html?api=t02-iam">abrir</a></td></tr><tr><td>T03</td><td>Experiencia, design system, marca por tenant, diccionario de términos y etiquetas, layouts y mapa del sitio</td><td>Definir, de una sola vez y para todas las aplicaciones de GoodApps Cooperativas (admin web, PWA del socio, PWA del empleado, PWA de campo, landing pública y consola de plataforma), cómo se ve, cómo se navega, cómo habla y cómo se adapta a cada cooperativa la interfaz, de modo que: Cada módulo M01–M19 y cada…</td><td>56</td><td><a href="./18-catalogo-endpoints/t03-uxd">t03-uxd</a></td><td><a href="./18-swagger/index.html?api=t03-uxd">abrir</a></td></tr><tr><td>T04</td><td>Configuración versionada, parámetros, tablas maestras y geografía</td><td>Proveer a GoodApps Cooperativas un motor de configuración único, tipado, versionado y auditable por tenant que: Reemplace la tabla clave/valor VARIABLE (y VARIABLE_PMOVIL) de ProCoop —1.536 parámetros identificados con…; Garantice que cada cambio de configuración se publique como una versión coherente (AGR-009): con…</td><td>106</td><td><a href="./18-catalogo-endpoints/t04-cfg">t04-cfg</a></td><td><a href="./18-swagger/index.html?api=t04-cfg">abrir</a></td></tr><tr><td>T06</td><td>Integraciones externas: marco común de conectores y fichas</td><td>Definir una sola arquitectura de integración para todo GoodApps Cooperativas y la ficha completa de cada integración externa que el sistema necesita para reemplazar a ProCoop y cumplir la BASE.</td><td>74</td><td><a href="./18-catalogo-endpoints/t06-int">t06-int</a></td><td><a href="./18-swagger/index.html?api=t06-int">abrir</a></td></tr><tr><td>T07</td><td>Migración desde ProCoop, convivencia, corrida paralela y by-pass</td><td>Definir, de forma ejecutable y comprobable, cómo se trasladan los datos de cada cooperativa que hoy opera con ProCoop (SQL Server + aplicación .NET de escritorio + portal CoopOnline sobre MySQL) a GoodApps Cooperativas (SaaS multitenant sobre MongoDB, DEC-001/DEC-002), y cómo se convive con ProCoop hasta apagarlo, sin…</td><td>54</td><td><a href="./18-catalogo-endpoints/t07-mig">t07-mig</a></td><td><a href="./18-swagger/index.html?api=t07-mig">abrir</a></td></tr><tr><td>T08</td><td>Requisitos no funcionales, seguridad, privacidad, observabilidad y calidad</td><td>Fijar, con métricas y criterios verificables, cómo debe comportarse GoodApps Cooperativas en todos sus módulos y canales, de modo que el equipo (o Cursor por olas) construya desde O0 una base técnica que no haya que rehacer: Rendimiento y capacidad: tiempos de respuesta por tipo de pantalla y operación, metas de…</td><td>63</td><td><a href="./18-catalogo-endpoints/t08-nfr">t08-nfr</a></td><td><a href="./18-swagger/index.html?api=t08-nfr">abrir</a></td></tr><tr><td>T09</td><td>Comunidad y comunicaciones (muro, novedades, encuestas, eventos, beneficios, audiencias, notificaciones y campañas)</td><td>Dar a cada cooperativa (tenant) un único sistema de relación con su comunidad —socios, titulares, adherentes, empleados, consejeros y público de la landing— que cubra: Comunicación editorial (DEC-008): un muro donde publica la cooperativa y sus empleados autorizados; los…; Participación no vinculante: encuestas…</td><td>326</td><td><a href="./18-catalogo-endpoints/t09-com">t09-com</a></td><td><a href="./18-swagger/index.html?api=t09-com">abrir</a></td></tr><tr><td>T10</td><td>Reportes, BI, tableros, exportaciones y APIs para terceros</td><td>Dar a cada cooperativa (tenant), a la plataforma y a terceros autorizados una capa única, gobernada y reproducible de consulta y explotación de datos, que reemplace y mejore todo lo que ProCoop ofrece en &quot;Informes&quot;, &quot;Reportes&quot;, &quot;Tablero de Control&quot;, &quot;Editor de Reportes&quot;, &quot;Informes Personalizados&quot;, &quot;Exportador&quot;…</td><td>136</td><td><a href="./18-catalogo-endpoints/t10-bia">t10-bia</a></td><td><a href="./18-swagger/index.html?api=t10-bia">abrir</a></td></tr><tr><td>T10 (externa)</td><td>API externa de integración (T10 §11.2.6)</td><td>API para sistemas de terceros (T10 §11.2.6): expone datos de la cooperativa a integradores autorizados con credenciales de cliente OAuth 2.0 o clave de API, scopes por recurso, límites de uso y sincronización incremental. Cada endpoint indica qué módulo provee el dato.</td><td>66</td><td><a href="./18-catalogo-endpoints/t10-bia-api-externa">t10-bia-api-externa</a></td><td><a href="./18-swagger/index.html?api=t10-bia-api-externa">abrir</a></td></tr><tr><td>T11</td><td>Workflow, eventos, tareas, aprobaciones y documentos</td><td>Definir el núcleo de coordinación de GoodApps, es decir, la infraestructura funcional que todos los módulos usan para: Comunicarse por eventos de dominio. Cada cambio confirmado publica un evento por el outbox transaccional…; Ejecutar procesos masivos y programados como jobs BullMQ. T11 aporta el catálogo consolidado…</td><td>120</td><td><a href="./18-catalogo-endpoints/t11-wfl">t11-wfl</a></td><td><a href="./18-swagger/index.html?api=t11-wfl">abrir</a></td></tr></tbody></table><h2 id="como-leer-cada-ficha" tabindex="-1">Cómo leer cada ficha <a class="header-anchor" href="#como-leer-cada-ficha" aria-label="Permalink to &quot;Cómo leer cada ficha&quot;">​</a></h2><p>Cada endpoint tiene una ficha con estos datos:</p><table tabindex="0"><thead><tr><th>Dato</th><th>De dónde sale</th></tr></thead><tbody><tr><td><strong>Qué hace</strong></td><td>La descripción de la fila API del anexo (§11), seguida de una frase armada con el método HTTP, la forma de la ruta y el nombre de la colección en T05.</td></tr><tr><td><strong>Para qué sirve</strong></td><td>El requisito funcional (RF) que el endpoint implementa, con su texto del §5 del anexo. Si la fila API o el anexo lo vinculan, se cita tal cual. Si no, se elige el RF del anexo con más palabras en común y se marca <em>a confirmar</em>.</td></tr><tr><td><strong>Quién lo usa</strong></td><td>El canal, según el prefijo de la ruta (backoffice, portal del socio, app de campo, consola de plataforma, terceros, público), y el permiso (capability) de T02.</td></tr><tr><td><strong>Recibe / Devuelve</strong></td><td>Parámetros, cuerpo y respuesta exitosa del contrato OpenAPI.</td></tr><tr><td><strong>Pantallas</strong></td><td>Pantallas del catálogo 4.5 que exigen el mismo permiso.</td></tr><tr><td><strong>Ola y fuente</strong></td><td>Ola de construcción y línea de la fila API en el anexo.</td></tr></tbody></table><h2 id="tabla-de-cobertura" tabindex="-1">Tabla de cobertura <a class="header-anchor" href="#tabla-de-cobertura" aria-label="Permalink to &quot;Tabla de cobertura&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Concepto</th><th>Universo</th><th>Cubierto</th><th>Cobertura</th><th>Observación</th></tr></thead><tbody><tr><td>Endpoints con ficha</td><td>4.193</td><td>4.193</td><td>100 %</td><td>Las mismas operaciones de <code>18-openapi/</code> y del visor Swagger.</td></tr><tr><td>APIs con propósito</td><td>30</td><td>30</td><td>100 %</td><td>§1 Objetivo de cada anexo (párrafo y lista); la API externa, de T10 §11.2.6.</td></tr><tr><td>Endpoints con requisito citado por el anexo</td><td>4.193</td><td>117</td><td>2,8 %</td><td>La fila API o un bloque del anexo nombra el RF.</td></tr><tr><td>Endpoints con requisito inferido</td><td>4.193</td><td>3.899</td><td>93,0 %</td><td>Marcados <em>a confirmar</em>; elegidos por coincidencia de palabras con los RF del anexo.</td></tr><tr><td>Endpoints sin requisito identificable</td><td>4.193</td><td>177</td><td>4,2 %</td><td>Coincidencia insuficiente; queda solo la descripción de la fila.</td></tr><tr><td>Endpoints con pantalla vinculada</td><td>4.193</td><td>2.923</td><td>69,7 %</td><td>Por igualdad de capability con el catálogo 4.5; el resto son integraciones, procesos o pantallas con otro permiso.</td></tr></tbody></table><h2 id="limitaciones" tabindex="-1">Limitaciones <a class="header-anchor" href="#limitaciones" aria-label="Permalink to &quot;Limitaciones&quot;">​</a></h2><ul><li><strong>Descripciones breves en el anexo.</strong> Muchas filas API describen el endpoint con dos o tres palabras (&quot;Maestros&quot;, &quot;RMA&quot;). La frase de &quot;Qué hace&quot; las completa con el método, la ruta y la colección, pero no agrega reglas que el anexo no dice.</li><li><strong>Respuestas sin estructura.</strong> 1.762 endpoints (42,0 %) devuelven un resultado genérico porque el anexo no define su estructura (acciones, tableros, simulaciones); se precisa en el diseño detallado de cada ola.</li><li><strong>Vínculo con requisitos.</strong> Los anexos casi nunca vinculan API con RF. El vínculo inferido acierta en la mayoría de los casos revisados por muestra, pero no siempre: hay que confirmarlo con el anexo antes de construir.</li><li><strong>Pantallas.</strong> Se vinculan por permiso; una pantalla puede usar endpoints con otro permiso (por ejemplo, lecturas de otro módulo) que no aparecen en la ficha.</li></ul>',15)])])}const g=e(r,[["render",i]]);export{m as __pageData,g as default};
